-- =====================================================================
-- Bean Culture — new booking page content (run once in the Supabase SQL Editor)
-- Only touches Bean Culture's booking settings and the "what to bring" text on its two courses.
--   • Phone on the page: 02 6223 2200
--   • 61 real reviews from classbento.com.au/bean-culture (first name + initial, wording unchanged)
--   • Real numbers: 280+ certificates issued, 5.0 on ClassBento (61), 4.8 on Google (88), up to 6 per class
--   • Course badges, what's covered, comparison table, reasons, FAQs and headings from your brief
-- Everything can be changed afterwards in Bookings → Website & settings → Booking page.
-- =====================================================================
update organisations set settings = jsonb_set(coalesce(settings, '{}'::jsonb), '{booking}',
  coalesce(settings->'booking', '{}'::jsonb) || jsonb_build_object(
    'intro', $j$Learn from the roasters at Bean Culture in Mitchell. Hands-on barista training for coffee lovers, home enthusiasts and anyone looking to work in a café.$j$,
    'faqs', $j$[{"q": "Is a barista course worth it?", "a": "Absolutely. A short amount of structured, hands-on training can save months of trial and error. You'll understand why your coffee tastes the way it does rather than simply following a recipe."}, {"q": "Can I learn barista skills on the job?", "a": "Some cafés do train inexperienced staff, but many employers prefer applicants who already understand grinder adjustment, espresso extraction and milk texturing. Our Looking For Work course is designed specifically to help bridge that gap."}, {"q": "Which course should I choose?", "a": "Choose Home Barista if you primarily want to make better coffee at home.\n\nChoose Looking For Work if you're hoping to work in a café or want a deeper understanding of commercial espresso preparation and workflow."}, {"q": "Do I receive a certificate?", "a": "Yes. Students receive a digital Bean Culture certificate after completing their course."}, {"q": "Do I need any experience?", "a": "No. Both courses are beginner friendly."}, {"q": "What should I bring?", "a": "Just yourself. We provide the coffee, milk, machines and training equipment.\n\nWear comfortable clothing; enclosed shoes are recommended."}, {"q": "Can I change my booking date?", "a": "Yes. You can move your booking to another date with availability up to 5 days before your course, online from your confirmation email, or give your spot to someone else."}, {"q": "Can I buy a course as a gift?", "a": "Yes. Gift vouchers can be used for any of our barista courses and are emailed to the recipient, straight away or on the day you choose."}, {"q": "Where are you?", "a": "Our roastery is at U5, 47-49 Vicars Street, Mitchell ACT. If you get lost, just give us a call on 02 6223 2200."}]$j$::jsonb,
    'landing', $j${"title": "Barista Courses Canberra | Bean Culture Coffee Roastery", "description": "Hands-on barista courses in Canberra at Bean Culture Coffee Roastery. Learn espresso, milk texturing, latte art and real café skills in small classes.", "headline": "Barista courses *in Canberra*", "heroImage": "https://www.eventureos.com.au/media/beanculture/looking-for-work-barista-course.jpg", "giftImage": "https://www.eventureos.com.au/media/beanculture/home-barista-course.jpg", "eyebrow": "Hands-on, real-world training", "phone": "02 6223 2200", "highlights": ["Small class sizes", "Hands-on training", "Expert local trainers", "Digital certificate included", "Real café equipment", "Free roastery tour"], "notes": ["Learn. Create. Belong.", "Great coffee starts here."], "stats": [{"value": "280+", "label": "students certified"}, {"value": "5.0 ★", "label": "61 reviews on ClassBento"}, {"value": "4.8 ★", "label": "88 Google reviews"}, {"value": "Up to 6", "label": "people per class"}], "reviews": [{"name": "Tasfia Q.", "date": "Aug 2026", "rating": 5, "text": "The teacher was fun and explained everything in details. We learnt so much about coffee from the seed to the flavourful coffee we drink. It is actually an art that needs precision", "course": null}, {"name": "Ann T.", "date": "Jul 2026", "rating": 5, "text": "This was a fantastic class!! The teacher was awesome and we learned so much. Being absolutely beginners at this he had so much patience with us and I can’t wait to go home and show off my new latte art skills.", "course": null}, {"name": "Kathleen D.", "date": "May 2026", "rating": 5, "text": "The class was informative and engaging. The teacher was very knowledgeable and able to answer all our questions, giving one-on-one guidance, advice and demonstrations. Highly recommend.", "course": null}, {"name": "Jacqobi R.", "date": "Feb 2026", "rating": 5, "text": "Teacher was amazing at explaining everything with what you need to do and how, amazing experience.", "course": null}, {"name": "Deepa", "date": "Jan 2026", "rating": 5, "text": "Very knowledgeable and personable with lots of information and very passionate about his art of Barista!!!", "course": null}, {"name": "Kelly M.", "date": "Jan 2026", "rating": 5, "text": "I had a fantastic afternoon learning about all things brewing coffee - from grinding the beans, pulling the perfect espresso shot, to getting beautiful, silky steamed milk. The teacher was a proper coffee nerd, and made every step seem easy and fun! I left the class feeling extra enthused and keen to apply what I have learned to my little machine at home. Thank you!!", "course": null}, {"name": "James E.", "date": "Jan 2026", "rating": 5, "text": "I picked a great day for the course and as everyone else had attended a morning session I scored a one-on-one learning class.\nMy teacher was incredibly friendly, approachable and knowledgeable being able to cater to what I wanted to learn and achieve in the class.\nI used some fantastic pieces of equipment which I wouldn't have had the opportunity otherwise. I was able to consider how I could adapt it to my home setup and what I should purchase in the future to further my craft.\nI can see how this would be great if you were a professional barista and wanted to focus on improving one or two certain aspects, being that you wouldn't often have time to focus and experiment much day-to-day.\nIt is also a great course if you just want to learn the process, recipe and how to make a great brew at home. If you have any semi-automatic style coffee machine you should be able to adapt it to home and learn what needs adjusting if certain aspects are not on point.", "course": null}, {"name": "Caila G.", "date": "Jan 2026", "rating": 5, "text": "Great teaching, great information, super enjoyable course.", "course": null}, {"name": "Theresa M.", "date": "Dec 2025", "rating": 5, "text": "Really enjoyed the class", "course": null}, {"name": "Mathew C.", "date": "Dec 2025", "rating": 5, "text": "Trainer was very knowledgeable and helpful.", "course": null}, {"name": "Trudy E.", "date": "Aug 2025", "rating": 5, "text": "Josh was very welcomed to my sister and I I ready enjoyed the Coffe course for the first time Josh was verwll experienced and fantastic teacher he answered my questions and it was very clear I really thought it was very fun and very thorough we did lots of practice coffee to grains, to milk to late art to clean up the clean up the coffee machine where that was very handy loved the coffee course worth doing in Canberra love do again one day soon course I would pass it on to other people too.", "course": null}, {"name": "Jenni E.", "date": "Aug 2025", "rating": 5, "text": "Josh was patient, understanding and took his time to explain how to use the coffee machines. We had fun with the latte art!", "course": null}, {"name": "Scott M.", "date": "Jul 2025", "rating": 5, "text": "The class was amazing for anyone wanting to make impressive coffee. Josh explained things thoroughly and it was a great day. End result below.", "course": null}, {"name": "Shanon G.", "date": "Apr 2025", "rating": 5, "text": "Josh was great very professional and has alot of good knowledge, would highly recommend, you could ask questions and he would tell and even show you how to do it, he would also check your work and give tips to improve so your next coffee would be better, I will definitely be recommending this place to anyone and will also be sending others there in the future to come. Great job Josh keep up the good work.", "course": null}, {"name": "Reetu B.", "date": "Jan 2025", "rating": 5, "text": "The overall experience is pretty good. I attached photo of how I did in my course.", "course": null}, {"name": "Yingjia W.", "date": "Jan 2025", "rating": 5, "text": "Excellent experience! Lucky for the class with just one student.", "course": null}, {"name": "Michael H.", "date": "Dec 2024", "rating": 5, "text": "Fantastic practical course with a great instructor. As we were only doing the course for home, for us he focused on what we needed to aim for to get the best out of the beans (and the latte art was a nice bonus :-). Well worth it and we're already putting what we learned into practice.", "course": null}, {"name": "Nebiat P.", "date": "Dec 2024", "rating": 5, "text": "I found this course very fun and enjoyable.", "course": null}, {"name": "Wayne R.", "date": "Apr 2024", "rating": 5, "text": "Natural teacher\nPassionate about his trade\nGreat resources\nGood knowledge and experience\nIt was great fun", "course": null}, {"name": "Wyn D.", "date": "Apr 2024", "rating": 5, "text": "Fantastic instructor and really informative course. He was really informative and covered a range of topics I didn’t know existed!", "course": null}, {"name": "Wenjiahui H.", "date": "Mar 2024", "rating": 5, "text": "Teacher Zee is my guide in the world of coffee. Not only has he taught me many techniques, but he has also ignited my passion for coffee with his enthusiasm. His patience and support have filled me with confidence during the learning process, and I am full of anticipation for my future in the coffee industry. Thank you, Teacher Zee, I will always cherish this valuable learning experience", "course": null}, {"name": "Lydia S.", "date": "Feb 2024", "rating": 5, "text": "Zee was a great teacher, very knowledgeable and passionate. A thoroughly enjoyable way to spend 2 hours :)", "course": null}, {"name": "Damian S.", "date": "Jan 2024", "rating": 5, "text": "Fantastic class. Well delivered. Instructor was clear and polished and gave good demonstrations\nI would recommend", "course": null}, {"name": "Wasamon P.", "date": "Dec 2023", "rating": 5, "text": "Great experiences, with 4 hours I could make many coffee and latte art as well. I also job a job after finish this course and plan to enroll more course in the future.", "course": null}, {"name": "Nina B.", "date": "Dec 2023", "rating": 5, "text": "Alessandro is an amazing teacher so patient and knowledgeable. Enjoy participating in Alessandro’s classes. Thank you for sharing your knowledge.", "course": null}, {"name": "Ugyen T.", "date": "Nov 2023", "rating": 5, "text": "It was a good sessions, engaging and enjoyable lesson. A facilitator was nice and the way he delivered was understandable and got opportunity to learn practically. Facility was equipped well and had a chance to learn everything individually with guidance from the facilitator. Overall, I love it.", "course": null}, {"name": "Derek J.", "date": "Nov 2023", "rating": 5, "text": "Really pleased with what was taught in the 2 hour session. Learning how to develop and stick to a coffee recipe, guidance on texturing milk and then trying my hand at latte art, all while getting lots of hands-on time using professional equipment was a really enjoyable experience.", "course": null}, {"name": "Thomas H.", "date": "Oct 2023", "rating": 5, "text": "I had a really great day thank you for this amazing and awesome opportunity and experience", "course": null}, {"name": "Jamie E.", "date": "Aug 2023", "rating": 5, "text": "This was such a great class. We did it for something fun and different to do, but it has given me a whole new respect for baristas and the science and precision behind good coffee. The instructor and venue were both great. Would highly recommend.", "course": null}, {"name": "Manas M.", "date": "Jul 2023", "rating": 5, "text": "Amazing teacher!\nWe learnt a lot! Amazing experience.\nWould love to taste the coffee at bean culture", "course": null}, {"name": "Sarah H.", "date": "Jun 2023", "rating": 5, "text": "The experience was great! Everything that we learnt was very interesting and informative. Loved steaming and making the milk/art. Sad that we didn't get to try it. Had tons of fun.", "course": null}, {"name": "Natasha H.", "date": "May 2023", "rating": 5, "text": "The man running the course was really lovely, he helped a lot and answered all my inquiries.\nWhere the course was located was spacious and clean.", "course": null}, {"name": "Harpreet S.", "date": "May 2023", "rating": 5, "text": "Professional and knowledgeable\nHelp understand coffee very nice\nNow I have more confidence in doing it", "course": null}, {"name": "Neroli S.", "date": "Apr 2023", "rating": 5, "text": "Teacher was very informative with background knowledge on beans before they are roasted. He explained everything clearly and made sure everyone was doing the different techniques correctly. Venue was set up nicely with all the equipment accessible. Thanks.", "course": null}, {"name": "Sahaja J.", "date": "Apr 2023", "rating": 4, "text": "Good nice place. Worried it wouldn’t be good for baristas but it really is", "course": null}, {"name": "Jan S.", "date": "Mar 2023", "rating": 5, "text": "Class very well presented, good sized class and as we just wanted to do home coffee making was great class with all participants doing the same. Highly recommend the course", "course": null}, {"name": "Lauren Z.", "date": "Feb 2023", "rating": 5, "text": "The course today was terrific. All of my questions were answered and shown. Great venue - love that we learned n a dedicated space in a working cafe\nLearning from a man who is passionate about his coffee, incredibly knowledgeable and very friendly made the hours pass very quickly.\nHaving a small group meant nothing was forgotten.\nLoved it! (Even if I will continue to draw stick flowers when trying to do latte art!)", "course": null}, {"name": "Khimkala S.", "date": "Feb 2023", "rating": 5, "text": "I absolutely loved learning about coffee, and I appreciated the teacher's method of starting from the beginning. I really did enjoy myself a lot. The instructor addressed all of our questions and made sure we were engaged in the material and having fun while learning it. I struggled with my artwork but he insisted in training me and gave me numerous opportunities to try. Totally enjoyed very bit of it.\nThank you so much.", "course": null}, {"name": "Nguyen H.", "date": "Dec 2022", "rating": 5, "text": "This course is valuable. I had new experiences and also learned the basics to advance about coffee. The teacher was very nice, he was willing to answer all questions.", "course": null}, {"name": "Heather M.", "date": "Dec 2022", "rating": 5, "text": "Everything was really well done and professional! The machines were new, well kept and high tech and the teacher did a really good job at explaining how things worked.", "course": null}, {"name": "Birat T.", "date": "Nov 2022", "rating": 5, "text": "Great treacher with lessons including the history of coffee and variations of drink.\nExcellent learning environment and methods.", "course": null}, {"name": "Isaac C.", "date": "Oct 2022", "rating": 5, "text": "Learnt alot, teacher was really friendly and the equipment was all very high tech\nWould highly recommend!", "course": null}, {"name": "Arna W.", "date": "Oct 2022", "rating": 5, "text": "What a great class and a great tutor.\nZ (he pronounced his name as that, but I dare say it's spelt in a longer way) was personable, patient and a what a pleasure to be a student in his class.\nFantastic coffee machines to learn on.", "course": null}, {"name": "Isabella W.", "date": "Sep 2022", "rating": 5, "text": "I did the introduction course with Amzah. I have no barista experience and found the course perfect. I learnt a lot. It’s a very detailed course but also easy to understand. I learnt how to use a grinder, make latte art, different coffee recipes and much more. Highly recommend!", "course": null}, {"name": "Bella E.", "date": "Aug 2022", "rating": 5, "text": "Trainer very great to teach how to operate espresso machine until latte art patiently. The way Zee deliver his message so clear.", "course": null}, {"name": "Marcus K.", "date": "Aug 2022", "rating": 5, "text": "I enjoyed using the barista machine and frothing milk and creating flower swirls and techniques", "course": null}, {"name": "Madilyn G.", "date": "Jul 2022", "rating": 5, "text": "Harmish (I can’t quite remember his name) was fantastic! He explained everything extremely well and was very patient. This course is value for money and I would definitely recommend this to anyone I know wanting to learn basics for making coffee", "course": null}, {"name": "Lee R.", "date": "Jul 2022", "rating": 5, "text": "Very knowledgeable and helpful teacher. I enjoyed the course and definitely learned plenty of things", "course": null}, {"name": "Kerry M.", "date": "Jul 2022", "rating": 5, "text": "Very informative teacher, good basic beginners class. I thought it was value for money with everything provided for the class.", "course": null}, {"name": "Hiroko M.", "date": "Jul 2022", "rating": 4, "text": "Quality of the teaching was very high, equipment was clean and functioned well. All around a good experience!", "course": null}, {"name": "Matt W.", "date": "Oct 2021", "rating": 5, "text": "We had a really great time doing this course - it was extremely informative, interesting, and fun! Highly recommend, especially to people who don't know much about coffee but would love to learn more :)", "course": null}, {"name": "Graham S.", "date": "Aug 2021", "rating": 5, "text": "Great! Enjoyed learning about the why’s rather than just ’do it my way’. Personable, patient and knew his stuff, always ready with an explanation and encouraging of my attempts at latte art. Many helpful hints. Fantastic!", "course": null}, {"name": "Emma S.", "date": "Jul 2021", "rating": 4, "text": "Very personable and encouraging teacher. Would have been good to have some typed notes provided to help with retention of information. My daughter really enjoyed the experience, as did I.", "course": null}, {"name": "Winona W.", "date": "Jun 2021", "rating": 5, "text": "Really helpful class! I learned a lot about coffee making and I enjoyed my time", "course": null}, {"name": "Steve B.", "date": "Mar 2021", "rating": 5, "text": "Great session, learned heaps. Justin was able to adjust the time to suit me skill level, answer all my questions and provide all manner of hints and tips to help me along.", "course": null}, {"name": "Michael H.", "date": "Feb 2021", "rating": 5, "text": "I was lucky enough to have a one on one lesson at Bean Coulture. Was shown the coffee machine, how to use it and clean it, and how to do the milk. Was a really good course and learnt a lot about coffee. Justin certainly had the knowledge and made it easy to learn how to brew. Highly recommended.", "course": null}, {"name": "Olivia F.", "date": "Feb 2021", "rating": 5, "text": "Really informative and was catered to our experience level. Even helped fix our grinder saving us from replacing it", "course": null}, {"name": "Toby C.", "date": "Sep 2020", "rating": 5, "text": "Toby felt very comfortable and enjoyed the class so much. Her teacher and the environment was fantastic. Would recommend this course for anyone who is interested in making a great coffee or a job in the industry.", "course": null}, {"name": "Benjamin M.", "date": "Jul 2020", "rating": 5, "text": "When I started I was alittle confused. The booking was strange (taked about haveing a party up to 20 poeple) and the loctaion was hard to find. But when I got there WOW, they where really friendly and as I have never poured a coffee they were able to teach really easily because of the equipment they had on hand. The best thing about it was the teacher Bardley, he is just a chill dude and instead of it feeling like a class. It felt I was on the first day on the job and he was my co-working just teaching me the ropes. I would really recomend just talking the course for any reason work or just to show off skill. (the photo below the left coffee was the last one I made and the right coffee was my first try.)", "course": null}, {"name": "Lin H.", "date": "Jun 2020", "rating": 5, "text": "trainer was very patient and such a fun environment to learn new things. I really enjoyed it.", "course": null}, {"name": "Jina J.", "date": "Oct 2019", "rating": 5, "text": "i had great experienced last thursday on my barista training.\nMy teach Shoan was quite passionable for teaching and i 100 recommend", "course": null}], "reviewsSource": {"label": "ClassBento", "url": "https://classbento.com.au/bean-culture"}, "gallery": [], "benefits": [{"title": "Real skills", "body": "Spend your time actually making coffee — not watching someone else do it."}, {"title": "Small groups", "body": "Small classes mean more machine time, individual feedback and fewer people waiting around."}, {"title": "Working roastery", "body": "Learn inside Bean Culture Coffee Roastery in Mitchell rather than a sterile classroom."}, {"title": "Learn from roasters", "body": "Understand what happens before the coffee even reaches the espresso machine."}, {"title": "Digital certificate", "body": "Receive a digital certificate when you successfully complete your course."}, {"title": "Roastery tour", "body": "See where our coffee is roasted and learn how roasting influences flavour and extraction."}], "courses": {"5fba2415-ef59-41cc-b8a2-cec5928c80a4": {"badge": "Perfect for coffee lovers", "points": ["Grinder adjustment and dosing", "Espresso extraction", "Milk texturing", "Latte art fundamentals", "Coffee recipes and ratios", "Common home coffee mistakes", "Cleaning and equipment care"], "bestFor": "Coffee lovers and home espresso users", "level": "Beginner friendly", "focus": "Better coffee at home"}, "f1bd855e-4fab-45af-a6e1-c271a1730d97": {"badge": "Get job ready", "points": ["Espresso theory", "Grinder calibration", "Shot preparation", "Milk texturing", "Latte art", "Café workflow", "Opening and closing procedures", "Cleaning and hygiene", "Customer service basics", "Job readiness advice"], "bestFor": "People wanting café employment", "level": "Beginner / job focused", "focus": "Real café barista skills"}}, "locationPoints": [], "locationImage": null, "copy": {"coursesEyebrow": "Our courses", "coursesTitle": "Choose your barista journey", "coursesIntro": "Whether you're brewing better coffee at home or chasing a career in cafés, our hands-on courses give you real skills, confidence and a deeper understanding of coffee.", "helpTitle": "Not sure which course?", "helpText": "Tell us what you're trying to achieve and we'll point you in the right direction.", "bookTitle": "Book your spot", "bookIntro": "Choose your course and find a date that works for you.\n\nOur classes are intentionally kept small so you get real time on the machine and personalised help from your trainer.", "bookPoints": "Instant confirmation\nSecure online booking\nSmall class sizes\nChange your date if required", "reviewsEyebrow": "Real stories", "reviewsTitle": "What our students say", "giftTitle": "Give the gift of great coffee", "giftText": "A Bean Culture barista course makes a brilliant gift for anyone who loves coffee. Gift vouchers can be used for any Bean Culture barista course and can be sent directly to the recipient.", "whyTitle": "More than just a barista course", "galleryTitle": "This isn't a classroom.\nIt's coffee training.", "compareTitle": "Which course is right for me?", "faqTitle": "Questions?", "locationTitle": "Learn inside a working Canberra roastery", "ctaEyebrow": "Ready to brew?", "ctaTitle": "Start your barista journey today.", "ctaText": "Whether you want café-quality coffee at home or the confidence to walk into your first barista job, we'll help you get there."}, "sections": []}$j$::jsonb
  )), updated_at = now()
where id = '56fbec7d-ff7b-4481-8b48-fd1bd1894fde';

update booking_courses set what_to_bring = $j$Just yourself. We provide the coffee, milk, machines and training equipment. Comfortable clothes and enclosed shoes are recommended.$j$
where organisation_id = '56fbec7d-ff7b-4481-8b48-fd1bd1894fde' and id in ('5fba2415-ef59-41cc-b8a2-cec5928c80a4', 'f1bd855e-4fab-45af-a6e1-c271a1730d97');

-- Check
select jsonb_array_length(settings->'booking'->'landing'->'reviews') as reviews,
       settings->'booking'->'landing'->>'phone' as phone,
       jsonb_array_length(settings->'booking'->'faqs') as faqs
from organisations where id = '56fbec7d-ff7b-4481-8b48-fd1bd1894fde';
